  "Название вина": "Мускатель белый",
  "Категория": "Белое",
  "Цвет": "Янтарно-золотистый, прозрачный",
  "Регион": "Крым",
  "Сорт винограда": "Белые сорта винограда",
  "Описание": "Аромат мускатный, цветочный с нотами акации, мёда и персика; вкус сладкий, гармоничный, с богатой мускатной ароматикой и долгим медово-цветочным послевкусием. К фруктовым десертам, выпечке, мягким сырам.",
  "Винодельня": "Массандра",
  "Slug": "massandra-muskatel-belyy-belye-sorta-vinograda-beloe-sladkoe-16",
  "Винтаж": "Нет данных",
  "Крепость, %": "16",
  "Крепость от, %": "16",
  "Крепость до, %": "16",
  "Сахар": "сладкое",
  "Игристое": "не определено",
  "Метод игристого": "Нет данных",
  "Креплёное": "Нет данных",
  "Безалкогольное": "Нет данных",
  "Органическое": "Нет данных",
  "Выдержка или резерв": "Нет данных"
}

